@extends('layout') @section('title',($record->exists?'Update ':'Create ').Str::singular($kind)) @section('content')<div class="page-head"><div><h1>{{ $record->exists?'Update':'Create' }} {{ Str::singular($kind) }}</h1><p class="subtext">Keep contact and address details ready for your next booking.</p></div><a class="button secondary" href="{{ route($kind.'.index') }}">← Back to {{ $kind }}</a></div><form method="post" action="{{ $record->exists?route($kind.'.update',$record):route($kind.'.store') }}">@csrf @if($record->exists)@method('PUT')@endif<div class="panel"><div class="panel-head"><h2>Contact details</h2></div><div class="panel-body form-grid">@foreach(['name'=>'Full name / company','phone'=>'Phone number','email'=>'Email address'] as $key=>$label)<label class="field">{{ $label }}<input name="{{ $key }}" type="{{ $key==='email'?'email':'text' }}" value="{{ old($key,$record->$key) }}" {{ $key==='email'?'':'required' }} maxlength="{{ $key==='phone'?40:255 }}"></label>@endforeach @php($extra=$kind==='vendors'?'contact_person':'tax_number')<label class="field">{{ $kind==='vendors'?'Contact person':'GST / tax number' }} <input name="{{ $extra }}" value="{{ old($extra,$record->$extra) }}" maxlength="100"></label><label class="field wide">Full address<textarea name="address" required maxlength="2000">{{ old('address',$record->address) }}</textarea><small>Include city, postcode and country.</small></label></div></div><div class="form-actions"><a class="button secondary" href="{{ route($kind.'.index') }}">Cancel</a><button class="button">{{ $record->exists?'Save changes':'Create '.Str::singular($kind) }}</button></div></form>@endsection